UPDATE "vault_item" SET "es" = $es${"title": "Correcciones ópticas", "summary": "Cinco sitios donde centrar con la regla se ve mal, cada uno con la línea de CSS que lo arregla: icono de play, icono con etiqueta, mayúsculas espaciadas, esquinas anidadas y una cita con la comilla colgada.", "use": "Úsala siempre que centres un icono, des padding a un botón, espacies mayúsculas, anides cajas redondeadas o compongas una cita destacada: los sitios donde un agente centra por geometría y lo da por hecho. Cada corrección es una clase independiente, así que coge solo la que necesites. Van medidas en em y porcentajes y siguen el tamaño del texto. Solo estructura: tipografía, color y espaciado salen del proyecto.", "tags": ["Solo CSS", "Alineación óptica", "Iconos", "Botones", "Interletraje", "Radio de borde", "Puntuación colgante", "Responsive"], "blocks": [{"title": "HTML", "note": "Cinco muestras independientes: quédate con la que necesites. El viewBox del icono de play tiene que ceñirse al triángulo; si no, el sexto se mide sobre espacio vacío y se pasa."}, {"title": "CSS", "note": "Los rellenos son provisionales: pon --optical-surface y --optical-ground con los del proyecto. Los 0.45em de la cita colgada dependen de la tipografía, así que compruébalos con la tuya."}]}$es$::jsonb WHERE "slug" = 'optical-corrections' AND "es" IS NULL;
--> statement-breakpoint
UPDATE "vault_item" SET "es" = $es${"title": "Slider de casos en cascada", "summary": "Un acordeón de fotos de casos de estudio: la abierta ocupa casi toda la fila y sus vecinas van menguando de ancho, con la frase del caso y su enlace cambiando debajo.", "use": "Úsala para enseñar de cinco a nueve casos o clientes en una fila, sin rejilla: cada caso sigue a la vista como una franja, uno está abierto y un único pie debajo cambia con él. Clic, deslizar, flechas y teclado; autoplay opcional que abre un caso al azar hasta que el visitante lo toca. Sin dependencias y cómoda para un CMS (cada slide lleva su pie y su enlace ocultos). Solo trae estructura y movimiento: el texto hereda la tipografía y el color del proyecto, así que sácalos del criterio. De tablet para abajo pasa a un slide cada vez.", "tags": ["Acordeón", "Slider", "Casos de estudio", "Vanilla JS", "Sin dependencias", "Autoplay", "Deslizar", "Teclado", "Flex", "Apta para CMS", "Responsive"], "blocks": [{"title": "HTML", "note": "Un .cascade_slide por caso. Su pie y su enlace viven en el [data-cascade-source] oculto (un párrafo con un <em> para la mitad más callada y luego un <a>). Mantén los pies de una longitud parecida para que el enlace de debajo no se mueva. Los logotipos son provisionales: pon el <img> o el SVG de la marca dentro de .cascade_logo. data-cascade-start marca el slide que abre primero; data-cascade-autoplay es la espera en ms, quítalo si no quieres autoplay."}, {"title": "CSS", "note": "Pon en --cascade-ground el color sobre el que se apoya el componente: la foto abierta se funde con él. El resto de variables son estructura (alto, separación, radio, los cinco anchos, la curva). No hay fuente, tamaño ni color de texto a propósito: salen del proyecto. Mantén el corte de 991px igual que MOBILE en el script."}, {"title": "JavaScript", "note": "Sin librerías. Pégalo antes de </body>; inicia cada [data-cascade] de la página. Las flechas dan la vuelta en escritorio y paran en los extremos en móvil. El autoplay se pausa fuera de pantalla y en una pestaña oculta, no corre con movimiento reducido y se para del todo con el primer clic, arrastre o tecla."}]}$es$::jsonb WHERE "slug" = 'cascading-case-slider' AND "es" IS NULL;
--> statement-breakpoint
UPDATE "vault_item" SET "es" = $es${"title": "Índice de proyectos en hélice de ladrillos", "summary": "Una fila de ladrillos en 3D, uno por proyecto, que gira como una hélice lenta; el cursor los ilumina, los levanta y los separa, y un clic abre una estantería de lomos con la portada elegida a lo ancho.", "use": "Para un índice de portfolio o de casos de entre 8 y 25 piezas que tenga que sentirse como un objeto y no como una rejilla. Cada ladrillo es un elemento de lista (nombre, tipo, año, color, enlace y una portada 5:2 opcional); la lista es lo único que se edita y sin JS sigue siendo una lista normal. El hover sigue la x del cursor, así que nunca pelea con el giro; el clic convierte la fila en un slider con anterior, siguiente, flechas del teclado y deslizar. Sin librerías ni canvas: transformaciones 3D de CSS y un script pequeño. En pantallas estrechas los ladrillos mantienen su tamaño y la fila se desliza de lado.", "tags": ["CSS 3D", "Vanilla JS", "Sin dependencias", "Hover", "Cursor", "Slider", "Portfolio", "Teclado", "Responsive", "Movimiento reducido"], "blocks": [{"title": "HTML", "note": "Un <li> por proyecto: --color es el color del ladrillo y el <img> su portada (5:2, opcional). Quita data-covers para ladrillos de color liso con la portada como miniatura en el pie. Los ladrillos, la estantería y los controles los monta el script a partir de esta lista."}, {"title": "CSS", "note": "Las propiedades personalizadas de arriba son lo que hay que ajustar: colores en reposo, tamaño del ladrillo (--helix-unit-max / -min), velocidad de giro, elevación y cuánto de la portada se ve en reposo. La tipografía se hereda de la página. Mantén width: 100% en .helix (un contenedor de tamaño se queda en 0 dentro de un padre que centra) y no pongas nunca mask, opacity, filter ni overflow en .helix__row ni en nada de dentro: aplana los ladrillos."}, {"title": "JavaScript", "note": "Cárgalo después del marcado. SPACING tiene que coincidir con el 0.55 del CSS; HOVER y REPEL son hasta dónde llega el cursor, en unidades de ladrillo. Sin portadas en la lista, un clic va directo al enlace del proyecto."}]}$es$::jsonb WHERE "slug" = 'brick-helix-work-index' AND "es" IS NULL;
